1	import { Injectable, signal } from '@angular/core';
2	
3	export type DialogType = 'danger' | 'warning' | 'info';
4	
5	export interface ConfirmOptions {
6	  title: string;
7	  message: string;
8	  confirmText?: string;
9	  cancelText?: string;
10	  type?: DialogType;
11	}
12	
13	interface DialogState {
14	  open: boolean;
15	  options: ConfirmOptions | null;
16	  resolve: ((value: boolean) => void) | null;
17	}
18	
19	@Injectable({ providedIn: 'root' })
20	export class DialogService {
21	  readonly state = signal<DialogState>({
22	    open: false,
23	    options: null,
24	    resolve: null
25	  });
